package dev.nijatva.reader.core.html

/**
 * Character references: the mechanism, and a bounded table.
 *
 * The table here is a documented **subset** — the named references that appear in real
 * articles. The full WHATWG table (2,231 entries) is generated by
 * `tools/generate-character-references` and is pinned by source URL and sha256; that
 * generator could not be run when this file was written because the specification host
 * was unreachable from the build environment. `docs/decisions/0002-character-references.md`
 * records that, and `docs/known-gaps.md` lists the missing names. Nothing here guesses:
 * a name that is not in the table is not decoded.
 */
object CharacterReferences {

    /**
     * Numeric references, plus the C1 remapping the specification requires: code points
     * 0x80–0x9F mean Windows-1252 characters, not the control codes.
     */
    private val C1_REMAP = mapOf(
        0x80 to '\u20AC', 0x82 to '\u201A', 0x83 to '\u0192', 0x84 to '\u201E',
        0x85 to '\u2026', 0x86 to '\u2020', 0x87 to '\u2021', 0x88 to '\u02C6',
        0x89 to '\u2030', 0x8A to '\u0160', 0x8B to '\u2039', 0x8C to '\u0152',
        0x8E to '\u017D', 0x91 to '\u2018', 0x92 to '\u2019', 0x93 to '\u201C',
        0x94 to '\u201D', 0x95 to '\u2022', 0x96 to '\u2013', 0x97 to '\u2014',
        0x98 to '\u02DC', 0x99 to '\u2122', 0x9A to '\u0161', 0x9B to '\u203A',
        0x9C to '\u0153', 0x9E to '\u017E', 0x9F to '\u0178',
    )

    /** Longest name first, so a greedy scan finds `&notin;` before `&not`. */
    private val NAMED: Map<String, String> = buildMap {
        fun ref(name: String, value: String) { put("$name;", value) }
        ref("amp", "&"); ref("lt", "<"); ref("gt", ">"); ref("quot", "\"")
        ref("apos", "'"); ref("nbsp", "\u00A0"); ref("copy", "\u00A9")
        ref("reg", "\u00AE"); ref("trade", "\u2122"); ref("hellip", "\u2026")
        ref("mdash", "\u2014"); ref("ndash", "\u2013"); ref("lsquo", "\u2018")
        ref("rsquo", "\u2019"); ref("ldquo", "\u201C"); ref("rdquo", "\u201D")
        ref("laquo", "\u00AB"); ref("raquo", "\u00BB"); ref("bull", "\u2022")
        ref("middot", "\u00B7"); ref("times", "\u00D7"); ref("divide", "\u00F7")
        ref("plusmn", "\u00B1"); ref("deg", "\u00B0"); ref("micro", "\u00B5")
        ref("para", "\u00B6"); ref("sect", "\u00A7"); ref("dagger", "\u2020")
        ref("Dagger", "\u2021"); ref("permil", "\u2030"); ref("prime", "\u2032")
        ref("Prime", "\u2033"); ref("euro", "\u20AC"); ref("pound", "\u00A3")
        ref("yen", "\u00A5"); ref("cent", "\u00A2"); ref("curren", "\u00A4")
        ref("frac12", "\u00BD"); ref("frac14", "\u00BC"); ref("frac34", "\u00BE")
        ref("sup1", "\u00B9"); ref("sup2", "\u00B2"); ref("sup3", "\u00B3")
        ref("iexcl", "\u00A1"); ref("iquest", "\u00BF"); ref("shy", "\u00AD")
        ref("macr", "\u00AF"); ref("acute", "\u00B4"); ref("cedil", "\u00B8")
        ref("ordf", "\u00AA"); ref("ordm", "\u00BA"); ref("not", "\u00AC")
        ref("uml", "\u00A8"); ref("brvbar", "\u00A6"); ref("larr", "\u2190")
        ref("uarr", "\u2191"); ref("rarr", "\u2192"); ref("darr", "\u2193")
        ref("harr", "\u2194"); ref("rArr", "\u21D2"); ref("lArr", "\u21D0")
        ref("hArr", "\u21D4"); ref("infin", "\u221E"); ref("ne", "\u2260")
        ref("le", "\u2264"); ref("ge", "\u2265"); ref("asymp", "\u2248")
        ref("sum", "\u2211"); ref("prod", "\u220F"); ref("radic", "\u221A")
        ref("int", "\u222B"); ref("part", "\u2202"); ref("nabla", "\u2207")
        ref("isin", "\u2208"); ref("notin", "\u2209"); ref("cap", "\u2229")
        ref("cup", "\u222A"); ref("sub", "\u2282"); ref("sup", "\u2283")
        ref("and", "\u2227"); ref("or", "\u2228"); ref("forall", "\u2200")
        ref("exist", "\u2203"); ref("empty", "\u2205"); ref("alpha", "\u03B1")
        ref("beta", "\u03B2"); ref("gamma", "\u03B3"); ref("delta", "\u03B4")
        ref("epsilon", "\u03B5"); ref("lambda", "\u03BB"); ref("mu", "\u03BC")
        ref("pi", "\u03C0"); ref("sigma", "\u03C3"); ref("omega", "\u03C9")
        ref("Delta", "\u0394"); ref("Omega", "\u03A9"); ref("Sigma", "\u03A3")
        ref("Pi", "\u03A0"); ref("hearts", "\u2665"); ref("diams", "\u2666")
        ref("clubs", "\u2663"); ref("spades", "\u2660"); ref("loz", "\u25CA")
        ref("star", "\u2606"); ref("starf", "\u2605"); ref("check", "\u2713")
        ref("cross", "\u2717"); ref("thinsp", "\u2009"); ref("ensp", "\u2002")
        ref("emsp", "\u2003"); ref("zwnj", "\u200C"); ref("zwj", "\u200D")
        ref("lrm", "\u200E"); ref("rlm", "\u200F"); ref("sbquo", "\u201A")
        ref("bdquo", "\u201E"); ref("lsaquo", "\u2039"); ref("rsaquo", "\u203A")
        ref("oelig", "\u0153"); ref("OElig", "\u0152"); ref("scaron", "\u0161")
        ref("Scaron", "\u0160"); ref("yuml", "\u00FF"); ref("fnof", "\u0192")
        ref("circ", "\u02C6"); ref("tilde", "\u02DC")
    }

    /** Names that also decode without the trailing semicolon, as the specification allows. */
    private val LEGACY = setOf("amp", "lt", "gt", "quot", "nbsp", "copy", "reg")

    private val MAX_NAME = NAMED.keys.maxOf { it.length }

    /**
     * Decodes the reference that starts at [start] (which points at `&`).
     *
     * Returns null when this is not a reference. In an attribute, a legacy name without a
     * semicolon followed by an alphanumeric is left as literal text — the "ambiguous
     * ampersand" rule, which is the single most commonly mis-implemented part of this
     * state.
     */
    fun decode(text: String, start: Int, inAttribute: Boolean): Result? {
        val limit = minOf(text.length, start + 1 + MAX_NAME + 1)
        var i = start + 1
        if (i >= limit) return null

        if (text[i] == '#') {
            i++
            val hex = i < limit && (text[i] == 'x' || text[i] == 'X')
            if (hex) i++
            val digitsStart = i
            var value = 0
            while (i < limit) {
                val d = digitValue(text[i], hex)
                if (d < 0) break
                value = value * (if (hex) 16 else 10) + d
                if (value > 0x10FFFF) value = 0x110000
                i++
            }
            if (i == digitsStart) return null
            if (i < text.length && text[i] == ';') i++
            return Result(numeric(value), i - start)
        }

        var best: String? = null
        var bestLength = 0
        var scan = start + 1
        val scanEnd = minOf(text.length, start + 1 + MAX_NAME)
        while (scan < scanEnd) {
            scan++
            val candidate = text.substring(start + 1, scan)
            if (NAMED.containsKey(candidate)) {
                best = candidate
                bestLength = candidate.length
            }
        }
        if (best != null) {
            return Result(NAMED.getValue(best), bestLength + 1)
        }

        // no semicolon form: only the legacy names, and only when it is unambiguous
        val legacyEnd = minOf(text.length, start + 1 + 4)
        var name = ""
        var j = start + 1
        while (j < legacyEnd && text[j].isLetter()) { name += text[j]; j++ }
        if (name in LEGACY) {
            val next = if (j < text.length) text[j] else ' '
            if (inAttribute && (next.isLetterOrDigit() || next == '=')) return null
            return Result(NAMED.getValue("$name;"), name.length + 1)
        }
        return null
    }

    data class Result(val text: String, val consumed: Int)

    private fun numeric(value: Int): String {
        if (value == 0 || value > 0x10FFFF || value in 0xD800..0xDFFF) return "\uFFFD"
        C1_REMAP[value]?.let { return it.toString() }
        return String(java.lang.Character.toChars(value))
    }

    private fun digitValue(c: Char, hex: Boolean): Int = when {
        c in '0'..'9' -> c - '0'
        hex && c in 'a'..'f' -> c - 'a' + 10
        hex && c in 'A'..'F' -> c - 'A' + 10
        else -> -1
    }

    /** Exposed for the test that counts coverage against the specification table. */
    val knownNameCount: Int get() = NAMED.size
}
